with --bgColor-muted; cover it with the card colour */
   #bg { fill: #ffffff; }
   @media (prefers-color-scheme: dark) { #bg { fill: #0d1117; } }

   .txt {
     font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
     font-size: 30px;
     font-weight: 700;
     fill: #C0762E;
   }
   /* type once on load, then hold — never blank the heading out again */
   #mask  { width: 0;
            animation: reveal 1.7s steps(13, end) .3s forwards; }
   #caret { fill: #C0762E;
            animation: reveal-caret 1.7s steps(13, end) .3s forwards,
                       blink 1.06s steps(1, end) infinite; }

   @keyframes reveal       { to { width: 238px; } }
   @keyframes reveal-caret { to { transform: translateX(234px); } }
   @keyframes blink        { 0%, 50% { opacity: 1; } 50.01%, 100% { opacity: 0; } }

   @media (prefers-reduced-motion: reduce) {
     #mask  { animation: none; width: 238px; }
     #caret { animation: none; transform: translateX(234px); }
   }
